"""Generate paper-ready fragments and concise findings from saved JSON only."""
import sys,json,re
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
from wpc_core import *
def pct(r):return '--' if r.get('rate') is None else f"{100*r['rate']:.2f}"
def esc(s):
    return s.replace('\\',r'\textbackslash{}').replace('_',r'\_').replace('%',r'\%').replace('#',r'\#').replace('&',r'\&')
def table(path,headers,rows):
    columns='l'+'r'*(len(headers)-1)
    content=['% Generated by tools/v11/build_wpc_results.py; do not edit.',r'\begin{tabular}{@{}'+columns+r'@{}}',r'\toprule',' & '.join(map(esc,headers))+r' \\',r'\midrule']
    content+=[' & '.join(map(esc,map(str,row)))+r' \\' for row in rows];content += [r'\bottomrule',r'\end{tabular}']
    path.write_text('\n'.join(content)+'\n',encoding='utf-8')
def main():
    verify_freeze();s=read(OUT/'evaluation-summary.json')['data'];g=read(OUT/'codemapper-reproduction-native-final.json')['data'];p=read(OUT/'paired-comparisons.json')['data']
    tex=OUT/'tex';tex.mkdir(exist_ok=False)
    selected=['t0.85-deployed','t0.85-IG+AG+VW','t0.55-IG+AG+VW','cascade_v1','tracker_adapter','gumtree','codemapper']
    placement=[];safety=[]
    for name in ('controlled:main','controlled:replication','real','real:oss:targeted','original:same-file','real:same-file','external:human-AB','external:human-AB:non-Python-code'):
        if name not in s['strata']:continue
        for method in selected:
            if method not in s['strata'][name]['methods']:continue
            m=s['strata'][name]['methods'][method]
            placement.append([name,method,m['n'],pct(m['accuracy']),pct(m['range_correct']),m['execution_errors']])
            safety.append([name,method,pct(m['missed']),pct(m['false_recheck']),pct(m['wrong']),pct(m['wrong_silent']),pct(m['lost'])])
    # Split tables to avoid an unbounded tabular exceeding one page.
    for i in range(0,len(placement),14):table(tex/f'table-placement-{i//14+1}.tex',['Population','Method','N','Correct %','Range %','Errors'],placement[i:i+14])
    for i in range(0,len(safety),14):table(tex/f'table-safety-{i//14+1}.tex',['Population','Method','Miss %','False %','Wrong %','Silent %','Lost %'],safety[i:i+14])
    ext=[];language=[];variants=[]
    for name,x in s['strata'].items():
        if name.startswith('external:human-AB:language:'):
            for method in selected:
                m=x['methods'][method];c=m['characters']['upstream'];language.append(['Human A/B '+name.split(':',3)[3],method,m['n'],pct(m['accuracy']),pct(c['exact']),f"{c['precision']:.3f}",f"{c['recall']:.3f}",f"{c['f1']:.3f}"])
        if name.startswith('external:language:'):
            for method in selected:
                m=x['methods'][method];c=m['characters']['upstream'];language.append([name.split(':',2)[2],method,m['n'],pct(m['accuracy']),pct(c['exact']),f"{c['precision']:.3f}",f"{c['recall']:.3f}",f"{c['f1']:.3f}"])
        if name in ('external:annotation_a','external:annotation_b','external:suppression','external:variable_test','external:block_test','external:method_test'):
            for method,m in x['methods'].items():
                c=m['characters']['upstream'];row=[name.split(':')[1],method,m['n'],pct(m['accuracy']),pct(c['exact']),f"{c['precision']:.3f}",f"{c['recall']:.3f}",f"{c['f1']:.3f}",m['execution_errors']]
                (variants if method.startswith('t') else ext).append(row)
    for kind,rows,headers in [('external',ext,['Dataset','Method','N','Line %','Exact %','Prec.','Recall','F1','Errors']),('variants',variants,['Dataset','Variant','N','Line %','Exact %','Prec.','Recall','F1','Errors']),('languages',language,['Language','Method','N','Line %','Exact %','Prec.','Recall','F1'])]:
        for i in range(0,len(rows),16):table(tex/f'table-{kind}-{i//16+1}.tex',headers,rows[i:i+16])
    reproductions=[]
    for name,x in g['datasets'].items():reproductions.append([name,x['observed']['n'],int(x['published']['exact']),x['observed']['exact']['k'],pct(x['observed']['exact']),'yes' if x['exact_reproduction'] else 'no'])
    table(tex/'table-codemapper-reproduction.tex',['Dataset','N','Published exact','Fresh exact','Fresh %','Reproduced'],reproductions)
    macros=dict(WpcObservations=s['n'],WpcDisagreements=s['disagreement_count'],WpcBlindedCases=read(OUT/'packet-manifest.json')['data']['n'])
    (tex/'numbers-wpc.tex').write_text('\n'.join(r'\newcommand{\n'+k+'}{'+str(v)+'}' for k,v in macros.items())+'\n',encoding='utf-8')
    winners=[]
    for name,x in s['strata'].items():
        if name.startswith('external:') and ':language:' not in name and name.count(':')>1:continue
        if name.startswith('real:class:') or name.startswith('real:project:'):continue
        base=x['methods'].get('t0.85-deployed')
        if not base:continue
        for method in ('gumtree','codemapper'):
            other=x['methods'].get(method)
            if other and other['accuracy']['k']>base['accuracy']['k']:winners.append(dict(stratum=name,method=method,correct=other['accuracy']['k'],cascade_correct=base['accuracy']['k'],n=x['n']))
    write('report-data.json',dict(winning_strata=winners,macros=macros,tex_files={p.name:sha(p) for p in tex.glob('*.tex')}),[OUT/'evaluation-summary.json',OUT/'paired-comparisons.json',OUT/'codemapper-reproduction-native-final.json'])
    def summary(name,method):
        m=s['strata'][name]['methods'][method];return f"{m['accuracy']['k']}/{m['n']} ({pct(m['accuracy'])}%)"
    human=s['strata']['external:human-AB:non-Python-code']['methods'];hc=s['strata']['external:human-AB']['methods']
    lines=['# WP C results','', '## Top findings','',
      f"1. GumTree beats deployed on real-history placement: {summary('real','gumtree')} versus {summary('real','t0.85-deployed')}; public edit-targeted: {summary('real:oss:targeted','gumtree')} versus {summary('real:oss:targeted','t0.85-deployed')}. The oracle shares AST construction, so this is not independent human validation.",
      f"2. On {human['t0.85-deployed']['n']} human-annotated non-Python code regions, deployed line accuracy is {pct(human['t0.85-deployed']['accuracy'])}%; combined .85 is {pct(human['t0.85-IG+AG+VW']['accuracy'])}%; combined .55 is {pct(human['t0.55-IG+AG+VW']['accuracy'])}%. Exact-character accuracy is separately {pct(human['t0.85-deployed']['characters']['upstream']['exact'])}%, {pct(human['t0.85-IG+AG+VW']['characters']['upstream']['exact'])}% and {pct(human['t0.55-IG+AG+VW']['characters']['upstream']['exact'])}%. Start and boundary recovery therefore require separate interpretation.",
      f"3. CodeMapper exact characters on human A/B: {hc['codemapper']['characters']['upstream']['exact']['k']}/{hc['codemapper']['n']}, versus deployed {hc['t0.85-deployed']['characters']['upstream']['exact']['k']}/{hc['t0.85-deployed']['n']}. Published-number reproduction: **{'passed' if g['passed'] else 'not reproduced exactly'}** after source-compatible native resolver and separate missing-object acquisition repairs. See `codemapper-reproduction-native-repaired.json`; earlier failed runs remain. No archived outputs replace executions.",'',
      '## Gates and exact published comparison','',
      'Fresh Living Review reproduction passed 3,600 + 3,600 controlled observations and all 15,064 histories, retaining all 143 contextual-tracker errors. Every frozen B1 code/helper/protocol hash is checked before each batch and each frozen-family call. Protocol C and input/code snapshots are retained. The protocol was frozen before any independent-dataset or external-tool benchmark outputs were evaluated.','']
    for name,x in g['datasets'].items():lines.append(f"- {name}: fresh exact {x['observed']['exact']['k']}/{x['observed']['n']}; paper exact {int(x['published']['exact'])}; discrepancy fields: {', '.join(x['differences']) or 'none'}; input failures {x['input_failures']}, execution failures {x['execution_failures']}.")
    lines+=['','## C1/C2 — GumTree and real-history oracle','',
      'GumTree 4.1.0 official release, default SimpleGumtree matcher, Simplified Chawathe actions and explicit bundled tree-sitter-ng generators. Python grammar 0.25.0; binding 0.26.6; Java 26.0.1. Full source lines come directly from tree-sitter points, avoiding upstream hybrid byte-column/UTF-16 offsets. Parse recovery or missing nodes fail explicitly. Same-path scope and 60-second timeout are frozen. All parse failures remain in denominators.','']
    for name in ('controlled:main','controlled:replication','real','real:oss:targeted','original:same-file','real:same-file'):
        lines.append(f"- {name}: deployed {summary(name,'t0.85-deployed')}; GumTree {summary(name,'gumtree')}; CodeMapper {summary(name,'codemapper')}.")
    lines+=['','External-method placement wins over deployed (raw counts; not automatically statistically resolved):','']
    lines += [f"- {w['stratum']}: {w['method']} {w['correct']}/{w['n']}, deployed {w['cascade_correct']}/{w['n']}." for w in winners]
    lines+=['',f"Real-history disagreement frame: {s['disagreement_count']} observations. `disagreement-packet/` contains {macros['WpcBlindedCases']} fixed-seed stratified blinded cases, complete source and blank reviewer responses; `disagreement-key.json` is separate. No human adjudication has been performed. Execution failures are a distinct disagreement stratum. The Python-AST alignment oracle shares syntax-based construction with GumTree; agreement is not independent validation of semantic or review-concern identity.",'',
      '## C4 — CodeMapper baseline','',
      'CodeMapper is pinned at 944fa91e6b359322c1a91f255ed7f4dfc556b68f (MIT), installed in its own venv. Matching code is unchanged. The first frozen direct-rename adapter failed reproduction and is retained as codemapper_direct_adapter. The primary CodeMapper result uses unchanged upstream history traversal, replacing checkout with a virtual HEAD and explicit-revision Git log. This correction was separately registered in V11-WPC-NATIVE-RESOLVER-PROTOCOL.md after seeing the initial reproduction failure; it is not a new CodeMapper holdout. All native outputs and errors remain. Git diff algorithms/flags and 15-line contexts are unchanged; no parameter tuning used annotations. CodeMapper supplies mapping only and has no review-state model. Its unchanged/changed adapter compares native region text. Controlled trials have separate two-commit repositories; pinned histories are read only.','',
      '## C5 — Independent and non-Python data','',
      'Living Review inputs are restricted to the paired file(s), not complete project maps. This evaluates within-file transfer and does not establish full-project cross-file recovery. CodeMapper retains native Git-history path traversal; scope differences and same-file subsets are explicit. Character annotations are expanded to full occupied lines for line-anchor tools, without truth-column trimming. CodeMapper keeps native arbitrary-character regions. Line-only baselines have a marked original-height projection for character scoring, without claimed native end recovery. Both character and line metrics matter. Data A manually selects source/target regions; Data B automatically selects AST/sibling/line source regions and manually annotates targets. Suppression is tool-derived/author-validated; Java data derives from CodeTracker histories and AST extents. Those datasets are not equivalent kinds of human ground truth.','']
    for name in ('external:human-AB','external:human-AB:non-Python-code'):
        for method in selected:
            m=s['strata'][name]['methods'][method];c=m['characters']['upstream'];lines.append(f"- {name}, {method}: line {m['accuracy']['k']}/{m['n']} ({pct(m['accuracy'])}%); exact characters {c['exact']['k']}/{c['n']} ({pct(c['exact'])}%); F1 {c['f1']:.3f}; errors {m['execution_errors']}.")
    lines+=['','All 16 frozen combinations at .85/.55, conventional baselines and each actual source language are in `evaluation-summary.json` and generated TeX. Other extensions (documentation/configuration) are separate from nominal repository language. Both positional character intersection and upstream longest-common-substring/rounding conventions are retained. Correct explicit deletions receive upstream exact/precision/recall/F1 credit; execution failures never do.','',
      '## Inference, failures and deviations','',
      'Paired exact conditional binomial tests and 10,000 fixed-seed cluster bootstraps compare both external tools with deployed and combined variants at .85/.55. Controlled clusters are source files, history clusters are commit pairs, external clusters are repository+commit pair. These are nominal exploratory intervals without multiplicity correction. Safety uses explicit variant request flags, and V7 range exactness uses the same surviving unambiguous subset.','',
      'Infrastructure events are retained: initial CodeMapper synthetic smoke failed because an empty external-diff executable was passed; the corrected --no-ext-diff smoke passed. The first GumTree job ended without completion; saved rows were preserved and only missing IDs resumed. Frozen variant families run behind a 60-second killable boundary to retain computational failures on large external regions; no frozen code changed. Code and protocol snapshots let readers distinguish acquisition, execution and reporting revisions.','',
      'Optional canonical LHDiff is unavailable: the author page has no runnable download link, the legacy author domain fails DNS, and the older software page supplies no artifact. Attempts and primary pages are retained. The earlier contextual tracker remains explicitly non-canonical.','',
      'DOX pass: `paper-drafts/AGENTS.md` owns this isolated research work and remains sufficient. All AGENTS.md files are intentionally unchanged under the explicit user prohibition. No application or earlier draft/evidence edits, project commits/pushes, external messages, delegated agents or new conversations. Two-commit synthetic fixtures remain inside WP C evidence as C4 requires. This package adds no manuscript revision, human adjudication or educational-effectiveness study.','',
      '## Paths and reproduction','',
      '- Code: `paper-drafts/tools/v11/*wpc*` and `WpcGumTree.java`.',
      '- Protocol: `review/V11-PROTOCOL-C.md`; freeze: `evidence/v11-wpc/protocol-freeze.json`.',
      '- Evidence and failure logs: `evidence/v11-wpc/`; external pins/manifests/venv: `tools/v11-ext/`.',
      '- Generated TeX: `evidence/v11-wpc/tex/`; final artifact verifier: `verification.json`.',
      '- Use the CodeMapper venv interpreter with `-I -B`. Stage scripts use exclusive output files; do not overwrite a completed run. Incomplete stage resume skips only saved observation IDs. Reaggregation and verification read retained inputs and outputs.']
    (ROOT/'review/V11-WPC-RESULTS.md').open('x',encoding='utf-8').write('\n'.join(lines)+'\n')
    print('generated',len(list(tex.glob('*.tex'))),'TeX files',flush=True)
if __name__=='__main__':main()
